{
  "name": "opencode-rtk-plugin",
  "version": "0.1.9",
  "description": "OpenCode v2 plugin that rewrites shell commands through rtk to cut LLM token usage by 60-90%.",
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": "./index.js"
  },
  "files": [
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "rtk",
    "token-optimization",
    "token-savings",
    "llm",
    "ai-coding-agent",
    "context-window",
    "shell"
  ],
  "license": "MIT",
  "author": "Nabheet S. Sandhu",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nabheet/opencode-rtk-plugin.git"
  },
  "bugs": {
    "url": "https://github.com/nabheet/opencode-rtk-plugin/issues"
  },
  "homepage": "https://github.com/nabheet/opencode-rtk-plugin#readme",
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "lint": "biome check . && markdownlint-cli2 \"**/*.md\" \"#node_modules/**\" \"#dist/**\" \"#.git/**\"",
    "lint:fix": "biome check --write . && markdownlint-cli2 --fix \"**/*.md\" \"#node_modules/**\" \"#dist/**\" \"#.git/**\"",
    "test": "node --check index.js && node --test test/*.test.mjs",
    "check": "npm run lint && npm test"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.6.4",
    "markdownlint-cli2": "^0.24.0"
  },
  "overrides": {
    "katex": "^0.19.1",
    "re2js": "2.8.7"
  }
}
